#b59b4e0c;padding:14px 18px;color:#dcd4ba;font-size:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{background:var(--panel);padding:24px;border:1px solid var(--line);border-radius:12px}.row{margin:15px 0}.row>div:first-child{display:flex;justify-content:space-between;gap:10px;font-size:14px}.bar{height:5px;background:#283e44;border-radius:9px;margin-top:8px}.bar i{height:5px;display:block;border-radius:9px;background:var(--mint)}.pressure .bar i{background:#d59c83}details{margin:18px 0;background:var(--panel);padding:20px 24px;border:1px solid var(--line);border-radius:12px}summary{cursor:pointer;color:var(--gold);font-weight:600}details[open]>summary{margin-bottom:18px}.shot{width:100%;height:auto;border-radius:8px}.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid var(--line);padding:11px}th{color:var(--muted)}footer{margin-top:40px;border-top:1px solid var(--line);padding:22px 0;color:var(--muted);font-size:12px}#boon-detail{position:fixed;z-index:10;width:390px;max-width:calc(100vw - 24px);max-height:calc(100vh - 32px);overflow:auto;border:1px solid var(--mint);border-radius:14px;background:#13262efc;box-shadow:0 15px 70px #000a;padding:22px}#boon-detail[hidden],[hidden]{display:none!important}#boon-detail img{width:84px;height:84px;object-fit:contain;float:left;margin:0 14px 12px 0}#boon-detail h3{font-size:22px;line-height:1.25}#detail-effect{clear:both;padding-top:12px;white-space:pre-line}#detail-close{float:right;background:none;border:0;font-size:24px;padding:0 0 4px 12px}#detail-meta{font-size:12px;color:var(--mint)}#detail-evidence{font-size:11px;color:var(--muted);border-top:1px solid var(--line);padding-top:12px}.empty{padding:24px;color:var(--muted)}@media(max-width:650px){main{padding:22px 16px}.top>div{padding:12px 16px;gap:15px}.wordmark{width:100%;margin:0}.hero{padding:26px}.hero p{max-width:100%}.stats{grid-template-columns:repeat(2,1fr)}.boons{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.boon{display:block;text-align:center;padding:12px 6px}.boon img{width:62px;height:62px}.boon strong{font-size:12px}.grid{grid-template-columns:1fr}.synergy{padding:20px}.toolbar input{flex-basis:100%}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.boon{transition:none}}@media print{.top,.toolbar,#boon-detail{display:none!important}body{background:white;color:#18302e}.hero,.panel,.synergy,.stat,.boon,details{background:#eff5f1;color:#18302e}.boon img{max-width:50px}.boons{grid-template-columns:repeat(3,1fr)}h1,h2,h3,.stat strong{color:#1e5144}.muted,small,footer{color:#47645b}}
</style></head><body><nav class='top' aria-label='Run sections'><div><span class='wordmark'>☾ GAME COACH</span><a href='#build'>Full build</a><a href='#synergies'>Synergies</a><a href='#results'>Results</a><a href='#timeline'>Timeline</a></div></nav><main>");
 b.Append("<header class='hero'><p class='eyebrow'>The chronicles / Hades II / Night "+r.number+"</p><span class='result'>"+H(r.result)+" · "+H(r.route)+"</span><h1>"+(r.cleared?"Victory earned.":"The next night awaits.")+"</h1><p style='margin-top:20px'>"+H(r.weapon)+" · "+H(r.aspect)+(r.aspectRank.HasValue?" · rank "+r.aspectRank:"")+"</p></header><div class='stats'>");
 string[] labels={r.cleared?"CLEAR TIME":"GAMEPLAY TIME","FEAR","ROOM VISITS","DAMAGE TAKEN"};string[] values={RecapPresentation.Time(r.victorySeconds??r.seconds),RunArchive.Number(r.fear),RunArchive.Number(r.rooms),RunArchive.Number(r.damageTaken)};for(int i=0;i<labels.Length;i++)b.Append("<div class='stat'><small>"+labels[i]+"</small><strong>"+values[i]+"</strong></div>");
 b.Append("</div><section id='build'><p class='eyebrow'>The whole toolkit</p><h2>Full build</h2><p class='muted'>Hover, focus or tap an icon for its level, rarity and recorded effect.</p><div class='toolbar'><input id='search' type='search' aria-label='Search build items' placeholder='Find a boon, Arcana or effect…'>");foreach(string cat in new[]{"All","Boons","Equipment","Arcana"})b.Append("<button class='filter' data-filter='"+cat+"' aria-pressed='"+(cat=="All"?"true":"false")+"'>"+cat+"</button>");b.Append("</div><div id='build-groups'>");
 foreach(string section in BuildSections.Names){var indices=Enumerable.Range(0,entries.Length).Where(i=>BuildSections.Category(entries[i])==section).ToArray();if(indices.Length==0)continue;b.Append("<section class='build-group' data-group='"+section+"' aria-labelledby='group-"+section+"'><h3 id='group-"+section+"'>"+section+" <small class='group-count'>"+indices.Length+" items</small></h3><div class='boons'>");
 foreach(int i in indices){var item=entries[i];string category=section;b.Append("<button class='boon "+H((item.rarity??"").ToLowerInvariant())+"' data-item='"+i+"' data-category='"+category+"' data-search='"+H((item.name+" "+item.category+" "+RecapDetails.Effect(item)).ToLowerInvariant())+"' aria-haspopup='dialog'>"+Art(item)+"<span><strong>"+H(item.name)+"</strong><small>"+H(RecapDetails.Rarity(item))+"</small></span></button>");}
 b.Append("</div></section>");}
 b.Append("</div><p id='no-results' class='empty' hidden>No matching items. Try another filter or search.</p><details id='text-loadout'><summary>Complete loadout · text version and provenance</summary><p class='muted'>This run's last retained checkpoint supplies levels and effects. Earlier keepsake swaps may appear in history. Unknown values remain unknown.</p>");foreach(string section in BuildSections.Names){var items=entries.Where(i=>BuildSections.Category(i)==section).ToArray();if(items.Length==0)continue;b.Append("<h3>"+section+"</h3>");foreach(var item in items)b.Append("<p><strong>"+H(item.name)+"</strong> · "+H(RecapDetails.Rarity(item))+"<br>"+H(string.IsNullOrEmpty(RecapDetails.Effect(item))?"Exact effect not retained.":RecapDetails.Effect(item))+"</p>");}b.Append("<p>Keepsakes used: "+H(string.Join(" → ",r.keepsakes))+"</p><p>Recorded Grasp: "+RunArchive.Number(r.grasp)+"</p></details></section><section id='synergies'><p class='eyebrow'>Why the pieces work</p><h2>The build, connected</h2><p class='muted'>Interactions and their conditions—not measured damage attribution.</p>");
 int n=0;foreach(var group in RunArchive.Groups(r)){b.Append("<article class='synergy'><span class='number'>"+(++n).ToString("00")+"</span><h3>"+H(group.title)+"</h3><p>"+H(group.why)+"</p><div class='components'>");foreach(var item in group.items){int id;if(map.TryGetValue(item.id,out id))b.Append("<button class='mini' data-item='"+id+"' aria-haspopup='dialog'>"+Art(item)+H(item.name)+"</button>");}b.Append("</div><div class='condition'><strong>To make it work</strong><br>"+H(group.condition)+"</div></article>");}if(n==0)b.Append("<p class='empty'>No supported synergy group is confirmed by the retained data. The complete build above remains available.</p>");
 b.Append("</section><section id='results'><h2>What the numbers show</h2><p class='muted'>"+H(r.damageEvidence??"Damage-source breakdown not retained")+".</p><div class='grid'>"+Bars(r.inflicted,"Most damage inflicted",false)+Bars(r.suffered,"Most damage suffered",true)+"</div><p class='muted' style='margin-top:16px'>Save-recorded totals: "+RunArchive.Number(r.damageDealt)+" dealt · "+RunArchive.Number(r.damageTaken)+" taken. Bars compare the listed sources, not percentages of total run damage.</p>");string screenshot=RunArchive.ImagePath(r);if(File.Exists(screenshot))b.Append("<details><summary>The victory screen</summary><img class='shot' alt='Victory screen captured for this run' src='data:image/jpeg;base64,"+Convert.ToBase64String(File.ReadAllBytes(screenshot))+"'></details>");
