 b.Append(Store.Json.Serialize(entries.Select(i=>new{name=i.name,meta=BoonArt.Meta(i),effect=string.IsNullOrEmpty(RecapDetails.Effect(i))?"Exact effect not retained for this run.":RecapDetails.Effect(i),evidence=i.evidence??"Game-save history. Exact levels may be unavailable.",image=BoonArt.Data(i.id)})).Replace("<","\\u003c").Replace(">","\\u003e").Replace("&","\\u0026"));
 b.Append(@"</script><script>
const data=JSON.parse(document.getElementById('build-data').textContent),tip=document.getElementById('boon-detail');let pinned=false,anchor=null,filter='All';
function hide(){tip.hidden=true;pinned=false;if(anchor)anchor.removeAttribute('aria-describedby')}
function show(button,pin=false){if(pinned&&!pin)return;const d=data[Number(button.dataset.item)];if(!d)return;if(anchor)anchor.removeAttribute('aria-describedby');anchor=button;pinned=pin;document.getElementById('detail-name').textContent=d.name;document.getElementById('detail-meta').textContent=d.meta;document.getElementById('detail-effect').textContent=d.effect;document.getElementById('detail-evidence').textContent=d.evidence;const img=document.getElementById('detail-image');img.hidden=!d.image;if(d.image)img.src=d.image;tip.hidden=false;button.setAttribute('aria-describedby','detail-effect');position(button)}
function position(button){const rect=button.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;let x=rect.right+12;if(x+w>innerWidth-12)x=Math.max(12,rect.left-w-12);let y=Math.max(12,Math.min(rect.top,innerHeight-h-12));if(innerWidth<650){x=(innerWidth-w)/2;y=Math.max(12,(innerHeight-h)/2)}tip.style.left=x+'px';tip.style.top=y+'px'}
document.querySelectorAll('[data-item]').forEach(button=>{button.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')show(button)});button.addEventListener('pointerleave',()=>{if(!pinned)hide()});button.addEventListener('focus',()=>show(button));button.addEventListener('blur',()=>{if(!pinned)hide()});button.addEventListener('click',()=>{show(button,true);document.getElementById('detail-close').focus()})});
document.getElementById('detail-close').addEventListener('click',()=>{let old=anchor;hide();if(old){old.focus();hide()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){let old=anchor;hide();if(old){old.focus();hide()}}});document.addEventListener('click',e=>{if(!tip.contains(e.target)&&!e.target.closest('[data-item]'))hide()});window.addEventListener('resize',()=>{if(!tip.hidden&&anchor)position(anchor)});window.addEventListener('scroll',()=>{if(!pinned)hide()});
function applyFilter(){hide();let n=0;const q=document.getElementById('search').value.toLowerCase().trim();document.querySelectorAll('.boon').forEach(b=>{b.hidden=(filter!=='All'&&b.dataset.category!==filter)||!b.dataset.search.includes(q);if(!b.hidden)n++});document.querySelectorAll('.build-group').forEach(group=>{const count=[...group.querySelectorAll('.boon')].filter(b=>!b.hidden).length;group.hidden=count===0;group.querySelector('.group-count').textContent=count+' '+(count===1?'item':'items')});document.getElementById('text-loadout').hidden=filter!=='All'||q.length>0;document.getElementById('no-results').hidden=n>0}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));applyFilter()}));document.getElementById('search').addEventListener('input',applyFilter);applyFilter();
</script></body></html>");return b.ToString();}
 static string Art(RecapItem item){string data=BoonArt.Data(item.id);return data.Length>0?"<img alt='' loading='lazy' src='"+data+"'>":"<span class='placeholder' aria-hidden='true'>◇</span>";}
 static string Bars(DamageRow[] rows,string title,bool pressure){var b=new StringBuilder("<article class='panel "+(pressure?"pressure":"")+"'><h3>"+H(title)+"</h3>");rows=rows??new DamageRow[0];double max=rows.Length==0?1:Math.Max(1,rows.Max(x=>x.amount));foreach(var row in rows)b.Append("<div class='row'><div><span>"+H(row.name)+"</span><strong>"+RunArchive.Number(row.amount)+"</strong></div><div class='bar' aria-hidden='true'><i style='width:"+(row.amount/max*100).ToString("F1",System.Globalization.CultureInfo.InvariantCulture)+"%'></i></div></div>");if(rows.Length==0)b.Append("<p class='muted'>Not retained for this night.</p>");return b.Append("</article>").ToString();}
